-- =====================================================================
-- Datos semilla: zonas, agencias/joyerías, jefes zonales y catálogo POP
-- real de Orocash. Generado a partir de 'agencias y zonales.xlsx'.
-- Los USUARIOS (admin + 10 jefes zonales) se crean con scripts/seed-users.ts
-- porque requieren el API de Supabase Auth (no se pueden insertar por SQL
-- plano con contraseña en texto).
-- =====================================================================


-- Agencias / joyerías reales (101), vinculadas a su zona por nombre.

-- Catálogo de materiales POP reales de Orocash
on conflict (name) do nothing;

select v.name, c.id, v.code, v.qty, v.qty, v.threshold
from (values
  ('VOLANTES de Compra', 'Volantes', 'VOL-001', 500, 20),
  ('VOLANTES de Venta', 'Volantes', 'VOL-002', 500, 20),
  ('VOLANTES de Graduación', 'Volantes', 'VOL-003', 300, 15),
  ('DÍPTICO joyas de inversión', 'Dípticos', 'DIP-001', 300, 15),
  ('SOBRES para contratos', 'Sobres', 'SOB-001', 1000, 50),
  ('TARJETAS de presentación', 'Tarjetas', 'TAR-001', 2000, 100),
  ('CERTIFICADOS de lingotes', 'Certificados', 'CERT-001', 500, 25),
  ('MISIÓN, VISIÓN Y VALORES', 'Institucional', 'INST-001', 110, 10),
  ('ACRÍLICO / hablador elevado', 'Acrílicos y Habladores', 'ACR-001', 110, 10),
  ('HABLADORES 20X20', 'Acrílicos y Habladores', 'HAB-001', 220, 20),
  ('ROMPETRÁFICO de PISO (estructura)', 'Rompetráficos', 'RT-000', 110, 10),
  ('ROMPETRÁFICO PUBLICIDAD de Grado', 'Rompetráficos', 'RT-001', 110, 10),
  ('ROMPETRÁFICO PUBLICIDAD de Compra', 'Rompetráficos', 'RT-002', 110, 10),
  ('ROMPETRÁFICO PUBLICIDAD de Venta', 'Rompetráficos', 'RT-003', 110, 10),
  ('ROMPETRÁFICO PUBLICIDAD de Relojería', 'Rompetráficos', 'RT-004', 110, 10),
  ('ROMPETRÁFICO PUBLICIDAD de Lingotes', 'Rompetráficos', 'RT-005', 110, 10)
) as v(name, category_name, code, qty, threshold)
join public.pop_categories c on c.name = v.category_name;
